class Solution { public double largestSumOfAverages(int[] nums,int k){int n=nums.length;double[] prefix=new double[n+1],dp=new double[n+1];for(int i=0;i<n;i++)prefix[i+1]=prefix[i]+nums[i];for(int i=1;i<=n;i++)dp[i]=prefix[i]/i;for(int group=2;group<=k;group++){double[] next=new double[n+1];for(int i=group;i<=n;i++)for(int cut=group-1;cut<i;cut++)next[i]=Math.max(next[i],dp[cut]+(prefix[i]-prefix[cut])/(i-cut));dp=next;}return dp[n];} }
